function PageTitle({ title, description, action }: { title: string; description: string; action?: ReactNode }) {
  return <div className="page-heading"><div className="page-heading-copy"><div className="page-eyebrow"><span className="eyebrow-dot" aria-hidden="true"/> AptoHire admin workspace</div><h1>{title}</h1><p>{description}</p></div>{action ? <div className="heading-actions">{action}</div> : null}</div>;
}
function BackToQueue({ target, label }: { target: string; label: string }) {
  return <button type="button" className="back-button" onClick={() => {
    const queue = document.getElementById(target);
    if (!queue) return;
    queue.focus({ preventScroll: true });
    queue.scrollIntoView({ behavior: window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth', block: 'start' });
  }}><ArrowLeft size={16} aria-hidden="true"/><span>{label}</span></button>;
}
function Loading({ text = 'Loading…' }: { text?: string }) { return <div className="empty-state" role="status"><div className="empty-orbit"/><strong>{text}</strong><span>Just a moment.</span></div>; }
function ErrorNotice({ retry }: { retry: () => void }) { return <div className="callout" role="alert"><AlertTriangle size={20}/><div><strong>We couldn't load this data.</strong><p className="muted" style={{ margin: '4px 0 10px' }}>Check your connection, then try again.</p><button className="button button-secondary button-small" onClick={retry}>Retry</button></div></div>; }
function Stats({ items }: { items: Array<{ value: string | number; label: string }> }) { return <div className="stats-row">{items.map((item, index) => <div className="stat" key={item.label} style={{ animationDelay: `${index * 55}ms` }}><span className="stat-label">{item.label}</span><span className="stat-value">{item.value}</span></div>)}</div>; }
function formatDate(value: string): string { return new Intl.DateTimeFormat('en-IN', { day: 'numeric', month: 'short', year: 'numeric' }).format(new Date(value)); }
function formatAge(value: string): string { const hours = Math.max(0, Math.floor((Date.now() - new Date(value).getTime()) / 3_600_000)); return hours < 24 ? `${hours}h ago` : `${Math.floor(hours / 24)}d ago`; }
/* eslint-disable-next-line jsx-a11y/no-noninteractive-tabindex -- scrollable table regions need keyboard access */
function Table({ headers, children, label }: { headers: string[]; children: ReactNode; label: string }) { return <div className="table-wrap"><div className="table-scroll" role="region" aria-label={`${label} table`} tabIndex={0}><table className="data-table" aria-label={label}><thead><tr>{headers.map((header) => <th scope="col" key={header}>{header}</th>)}</tr></thead><tbody>{children}</tbody></table></div></div>; }
function cell(label: string, content: ReactNode) { return <td data-label={label}>{content}</td>; }
function ErrorText({ error }: { error: Error | null }) { if (!error) return null; const message = error.message === 'CONFLICT' ? 'This item changed while you were working. Refresh and review it again.' : error.message === 'FORBIDDEN' ? 'You don’t have access to that action, or a different assigned reviewer is required.' : error.message === 'VALIDATION_FAILED' ? 'Check the selected values and required reason, then try again.' : error.message === 'NOT_FOUND' ? 'This item is no longer available. Refresh the page.' : 'We couldn’t reach AptoHire. Check your connection and try again.'; return <p className="field-hint" role="alert">{message}</p>; }
const freeEmailDomains = new Set(['gmail.com', 'yahoo.com', 'outlook.com', 'hotmail.com', 'icloud.com']);
function emailDomain(email: string): string { return email.trim().toLowerCase().split('@').at(-1) ?? ''; }
function normalizedDomain(value: string): string {
  let host = value.trim().toLowerCase();
  if (host.startsWith('https://')) host = host.slice(8);
  else if (host.startsWith('http://')) host = host.slice(7);
  if (host.startsWith('www.')) host = host.slice(4);
  return host.split(/[/:?#]/)[0] ?? '';
}
function validDomain(value: string): boolean {
  const parts = normalizedDomain(value).split('.');
  return parts.length >= 2 && parts.at(-1)!.length >= 2 && parts.every((part) => part.length <= 63 && /^[a-z0-9](?:[a-z0-9-]*[a-z0-9])?$/i.test(part));
}
function websiteMatchesContact(website: string | undefined, email: string): boolean {
  try {
    if (!website) return false;
    const host = normalizedDomain(new URL(website).hostname);
    const contact = emailDomain(email);
    return Boolean(host && contact && (host === contact || contact.endsWith(`.${host}`) || host.endsWith(`.${contact}`)));
  } catch { return false; }
}
function payloadText(value: unknown): string {
  if (value === null || value === undefined) return '—';
  if (typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean') return String(value);
  try { return JSON.stringify(value); } catch { return '[Sample value unavailable]'; }
}
function payloadLabel(key: string): string { return key.replaceAll('_', ' ').replaceAll('-', ' ').replace(/\b\w/g, (letter) => letter.toUpperCase()); }
function applicationDomains(item: Application): Set<string> { return new Set([...(item.emailDomains ?? []), emailDomain(item.contactEmail), item.website ? normalizedDomain(item.website) : ''].map((value) => normalizedDomain(value)).filter(Boolean)); }
function possibleDuplicate(left: Application, right: Application): boolean {
  if (left.id === right.id || left.type !== right.type) return false;
  const leftName = left.name.toLowerCase().replace(/[^a-z0-9]/g, ''); const rightName = right.name.toLowerCase().replace(/[^a-z0-9]/g, '');
  const leftDomains = applicationDomains(left); const rightDomains = applicationDomains(right);
  return Boolean(leftName && leftName === rightName) || [...leftDomains].some((domain) => rightDomains.has(domain));
}

export function ApprovalsPage() {
  const backend = useBackend(); const client = useQueryClient(); const toast = useToast(); const stepUp = useStepUp();
  const query = useQuery({ queryKey: ['approvals'], queryFn: () => backend.approvals() });
  const [kind, setKind] = useState<'university' | 'organization'>('university'); const [status, setStatus] = useState<Application['status']>('pending');
  const [selectedId, setSelectedId] = useState('uni-c'); const [search, setSearch] = useState('');
  const [dialog, setDialog] = useState<{ kind: 'approve' | 'reject' | 'subscription'; item: Application } | null>(null);
  const rows = (query.data ?? []).filter((item) => item.type === kind && item.status === status && `${item.name} ${item.reference}`.toLowerCase().includes(search.toLowerCase()));
  const selected = rows.find((item) => item.id === selectedId) ?? rows[0];
  const duplicates = selected ? (query.data ?? []).filter((item) => possibleDuplicate(selected, item)) : [];
  const universityDomains = selected?.emailDomains ?? [];
  const domainsValid = universityDomains.length > 0 && universityDomains.every(validDomain);
  const hasFreeMail = selected ? freeEmailDomains.has(emailDomain(selected.contactEmail)) : false;
  const orgDomainMatch = selected ? websiteMatchesContact(selected.website, selected.contactEmail) : false;
  const mutation = useMutation({ mutationFn: (data: { item: Application; action: 'approve' | 'reject'; note?: string }) => backend.decideApplication({ id: data.item.id, subjectId: data.item.subjectId, type: data.item.type, action: data.action, note: data.note }), onSuccess: async (_data, variables) => { toast(variables.action === 'approve' ? `${variables.item.type === 'university' ? 'University' : 'Organization'} approved.` : 'Application rejected.'); setDialog(null); await Promise.all([client.invalidateQueries({ queryKey: ['approvals'] }), client.invalidateQueries({ queryKey: ['counts'] }), client.invalidateQueries({ queryKey: ['audit-log'] })]); const next = rows.find((row) => row.id !== variables.item.id); if (next) setSelectedId(next.id); } });
  const subscription = useMutation({ mutationFn: ({ item, value }: { item: Application; value: 'active' | 'inactive' }) => backend.setSubscription(item.subjectId ?? item.id, value), onSuccess: async (_data, vars) => { toast(`Subscription ${vars.value === 'active' ? 'activated' : 'turned off'}.`); setDialog(null); await Promise.all([client.invalidateQueries({ queryKey: ['approvals'] }), client.invalidateQueries({ queryKey: ['audit-log'] })]); } });
  return <>
    <PageTitle title="Approvals" description="Review university and organization applications before access is granted." action={<button className="button button-secondary" onClick={() => { void query.refetch(); }}> <RefreshCw size={16}/> Refresh</button>} />
    <Stats items={[{ value: query.data?.filter((item) => item.status === 'pending').length ?? '—', label: 'Pending applications' }, { value: query.data?.filter((item) => item.status === 'approved').length ?? '—', label: 'Approved' }, { value: query.data?.filter((item) => item.status === 'rejected').length ?? '—', label: 'Rejected' }, { value: 'Sample', label: 'Queue data' }]} />
    <div className="tabs" role="tablist" aria-label="Application type"><button className="tab-button" role="tab" aria-selected={kind === 'university'} onClick={() => { setKind('university'); setSelectedId('uni-c'); }}>Universities</button><button className="tab-button" role="tab" aria-selected={kind === 'organization'} onClick={() => { setKind('organization'); setSelectedId('orbit'); }}>Organizations</button></div>
    <div className="toolbar"><div className="segmented" aria-label="Application status">{(['pending', 'approved', 'rejected'] as const).map((value) => <button key={value} aria-pressed={status === value} onClick={() => setStatus(value)}>{value[0]?.toUpperCase()}{value.slice(1)}</button>)}</div><label className="searchbox"><Search size={17}/><input className="input" placeholder="Search applications" value={search} onChange={(event) => setSearch(event.target.value)} aria-label="Search applications"/></label></div>
    {query.isLoading ? <Loading text="Loading applications"/> : query.isError ? <ErrorNotice retry={() => void query.refetch()}/> : <div className="split-layout"><div id="approval-queue" className="split-list" aria-label="Applications" tabIndex={-1}>{rows.length ? rows.map((item) => <button className={`list-item ${selected?.id === item.id ? 'active' : ''}`} key={item.id} onClick={() => setSelectedId(item.id)}><span className="list-item-title"><span>{item.name}</span><StatusChip status={item.status}/></span><span className="list-item-meta"><span className="mono">{item.reference}</span><span>{item.details}</span></span><span className="list-item-meta"><span>{formatAge(item.submittedAt)}</span>{item.rosterCount ? <span>{item.rosterCount} waiting</span> : null}</span></button>) : <div className="empty-state"><strong>{status === 'pending' ? 'No applications waiting.' : 'No applications in this view.'}</strong></div>}</div>
      {selected ? <section className="split-detail" aria-label={`${selected.name} application details`}><BackToQueue target="approval-queue" label="Back to applications"/><div style={{ display: 'flex', justifyContent: 'space-between', gap: 12, alignItems: 'flex-start' }}><div><span className="mono">{selected.reference}</span><h2 style={{ marginTop: 6 }}>{selected.name}</h2><p className="muted">{selected.details}</p></div><StatusChip status={selected.status}/></div>
        <div className="detail-section"><h3>Application</h3><dl className="detail-grid"><div className="detail-cell"><dt>Contact</dt><dd>{selected.contactName}, {selected.contactRole}</dd></div><div className="detail-cell"><dt>Email</dt><dd><a href={`mailto:${selected.contactEmail}`}>{selected.contactEmail}</a></dd></div><div className="detail-cell"><dt>Phone</dt><dd>{selected.contactPhone}</dd></div><div className="detail-cell"><dt>Submitted</dt><dd>{formatDate(selected.submittedAt)}</dd></div>{selected.website ? <div className="detail-cell"><dt>Website</dt><dd>{selected.website}</dd></div> : null}<div className="detail-cell"><dt>Reference</dt><dd className="mono">{selected.reference}</dd></div></dl>{selected.payload && Object.keys(selected.payload).length ? <><h4 style={{ margin: '14px 0 8px' }}>Additional application fields · Sample</h4><dl className="detail-grid">{Object.entries(selected.payload).map(([key, value]) => <div className="detail-cell" key={key}><dt>{payloadLabel(key)}</dt><dd>{payloadText(value)}</dd></div>)}</dl></> : null}</div>
        <div className="detail-section"><h3>Checks to consider</h3>
          {selected.type === 'university' ? <>
            <div className="check-row">{domainsValid ? <Check className="check-icon" size={18}/> : <AlertTriangle className="check-warning" size={18}/>}<span>{universityDomains.length ? domainsValid ? 'Submitted institutional email domains are well-formed.' : 'Check this: one or more submitted email domains look invalid.' : 'No institutional email domains were submitted.'}</span></div>
            <div className="check-row">{universityDomains.some((domain) => freeEmailDomains.has(normalizedDomain(domain))) ? <AlertTriangle className="check-warning" size={18}/> : <Check className="check-icon" size={18}/>}<span>{universityDomains.some((domain) => freeEmailDomains.has(normalizedDomain(domain))) ? 'Check this: a free-mail domain appears in the university domain list.' : 'No common free-mail domain is listed.'}</span></div>
            <div className="check-row"><Users size={18} className="check-icon"/><span>{selected.rosterCount ?? 0} roster entries are waiting. Only the count is shown here.</span></div>
          </> : <>
            <div className="check-row">{hasFreeMail ? <AlertTriangle className="check-warning" size={18}/> : <Check className="check-icon" size={18}/>}<span>{hasFreeMail ? 'Check this: the contact uses a common free-mail address.' : 'No common free-mail address detected for this contact.'}</span></div>
            <div className="check-row">{orgDomainMatch ? <Check className="check-icon" size={18}/> : <CircleHelp size={18} className="check-warning"/>}<span>{orgDomainMatch ? 'Website and contact email domains appear to match.' : 'Check this: website and contact email domains do not clearly match.'}</span></div>
          </>}
          <div className="check-row">{duplicates.length ? <AlertTriangle className="check-warning" size={18}/> : <Check className="check-icon" size={18}/>}<span>{duplicates.length ? `Check this: possible duplicate ${duplicates.length === 1 ? 'application' : 'applications'}: ${duplicates.map((item) => item.name).join(', ')}.` : 'No likely duplicate in the loaded applications.'} Similarity checks are advisory only.</span></div>
        </div>
        {selected.status === 'rejected' && selected.note ? <div className="callout"><FileText size={18}/><span>Rejection note: {selected.note}</span></div> : null}
        {selected.status === 'approved' && selected.type === 'organization' ? <div className="detail-section"><h3>Subscription</h3><p className="muted">Prototype billing switch for {selected.name}.</p><div className="action-row"><StatusChip status={selected.subscription ?? 'inactive'}/><button className="button button-secondary" onClick={() => setDialog({ kind: 'subscription', item: selected })}>{selected.subscription === 'active' ? 'Turn off subscription' : 'Activate subscription'}</button></div></div> : null}
        {selected.status !== 'approved' ? <div className="action-row">{selected.status === 'pending' ? <><button className="button button-primary" onClick={() => setDialog({ kind: 'approve', item: selected })}><Check size={17}/>Approve</button><button className="button button-secondary" onClick={() => setDialog({ kind: 'reject', item: selected })}>Reject</button></> : <button className="button button-primary" onClick={() => setDialog({ kind: 'approve', item: selected })}>Reconsider</button>}</div> : null}
      </section> : <div className="split-detail empty-state"><strong>Select an application</strong><span>Details and checks will appear here.</span></div>}</div>}
    {dialog?.kind === 'approve' ? <ConfirmForm title={dialog.item.status === 'rejected' ? 'Reconsider application?' : `Approve ${dialog.item.type}?`} consequence={dialog.item.type === 'university' ? `Approving unlocks registration for ${dialog.item.rosterCount ?? 0} rostered students and creates matches with existing profiles.` : 'Approving gives the Verified organization badge. Turn on the subscription separately.'} action="Approve" onCancel={() => setDialog(null)} onConfirm={() => { const item = dialog.item; setDialog(null); stepUp.requireStepUp(() => mutation.mutate({ item, action: 'approve' })); }}/>: null}
    {dialog?.kind === 'reject' ? <ConfirmForm title="Reject application?" consequence="This note may be shown to the applicant." action="Reject" needsReason reasonMin={10} onCancel={() => setDialog(null)} onConfirm={(note) => { const item = dialog.item; setDialog(null); stepUp.requireStepUp(() => mutation.mutate({ item, action: 'reject', note })); }}/>: null}
    {dialog?.kind === 'subscription' ? <ConfirmForm title={`${dialog.item.subscription === 'active' ? 'Turn off' : 'Activate'} subscription?`} consequence={dialog.item.subscription === 'active' ? `Turning this off blocks candidate matching and new access requests for ${dialog.item.name}.` : `This turns on the prototype subscription switch for ${dialog.item.name}.`} action={dialog.item.subscription === 'active' ? 'Turn off' : 'Activate'} onCancel={() => setDialog(null)} onConfirm={() => { const item = dialog.item; const value = item.subscription === 'active' ? 'inactive' : 'active'; setDialog(null); stepUp.requireStepUp(() => subscription.mutate({ item, value })); }}/>: null}
    {stepUp.modal}<ErrorText error={mutation.error ?? subscription.error}/>
  </>;
}

export function ReviewsPage() {
  const backend = useBackend(); const client = useQueryClient(); const toast = useToast(); const stepUp = useStepUp();
  const query = useQuery({ queryKey: ['reviews'], queryFn: () => backend.reviews() });
  const config = useQuery({ queryKey: ['config'], queryFn: () => backend.config() });
  const [selectedId, setSelectedId] = useState('rv-react-52'); const [mode, setMode] = useState<'pending' | 'decided'>('pending'); const [dialog, setDialog] = useState<'confirm' | 'adjust' | null>(null); const [evidenceOpen, setEvidenceOpen] = useState(false);
  const [score, setScore] = useState<number>(52); const [reason, setReason] = useState(''); const [filter, setFilter] = useState('all');
  const pending = (query.data ?? []).filter((row) => mode === 'pending' ? row.status === 'pending' : row.status !== 'pending').filter((row) => filter === 'all' || (filter === 'overdue' && new Date(row.dueAt) < new Date()));
  const sorted = [...pending].sort((a, b) => a.dueAt.localeCompare(b.dueAt)); const selected = sorted.find((row) => row.id === selectedId) ?? sorted[0];
  const mutation = useMutation({ mutationFn: (input: { score: number; reason?: string; adjusted: boolean }) => backend.decideReview(selected.id, input.score, input.reason, selected.skillId), onSuccess: async (_data, variables) => { toast(variables.adjusted ? 'Score adjusted.' : 'Review confirmed.'); setDialog(null); setReason(''); await Promise.all([client.invalidateQueries({ queryKey: ['reviews'] }), client.invalidateQueries({ queryKey: ['counts'] }), client.invalidateQueries({ queryKey: ['audit-log'] })]); const latest = client.getQueryData<ReviewItem[]>(['reviews']) ?? []; const next = latest.find((row) => row.id !== selected.id && row.status === 'pending'); if (next) { setSelectedId(next.id); document.getElementById('review-heading')?.focus(); } } });
  const passMark = config.data?.PASS_MARK ?? 50; const low = config.data?.BORDERLINE[0] ?? 40; const high = config.data?.BORDERLINE[1] ?? 60;
  const previewScore = dialog === 'adjust' ? score : selected?.score ?? 0;
  const level = previewScore <= 50 ? 'Emerging' : previewScore <= 69 ? 'Competent' : previewScore <= 84 ? 'Proficient' : 'Advanced';
  const verified = previewScore > passMark;
  return <>
    <PageTitle title="Reviews" description="Blind review of borderline results. Results stay private until a human decides." action={<div className="segmented"><button aria-pressed={mode === 'pending'} onClick={() => setMode('pending')}>Pending</button><button aria-pressed={mode === 'decided'} onClick={() => setMode('decided')}>Decided</button></div>} />
    <Stats items={[{ value: query.data?.filter((item) => item.status === 'pending').length ?? '—', label: 'Waiting for review' }, { value: query.data?.filter((item) => new Date(item.dueAt) < new Date() && item.status === 'pending').length ?? '—', label: 'Overdue' }, { value: `${low}–${high}`, label: 'Borderline range' }, { value: `>${passMark}`, label: 'Pass mark' }]} />
    <div className="toolbar"><select className="pill-filter" value={filter} onChange={(event) => setFilter(event.target.value)} aria-label="Filter reviews"><option value="all">All reviews</option><option value="overdue">Overdue only</option></select><span className="field-hint" aria-live="polite">{sorted.length} item{sorted.length === 1 ? '' : 's'} in this queue</span></div>
    {query.isLoading ? <Loading text="Loading reviews"/> : query.isError ? <ErrorNotice retry={() => void query.refetch()}/> : !selected ? <div className="empty-state"><div className="empty-orbit"/><strong>No reviews waiting.</strong><span>New borderline results will appear here.</span></div> : <>
      <div className="split-layout"><div id="review-queue" className="split-list" aria-label="Review queue" tabIndex={-1}>{sorted.map((item) => <button key={item.id} className={`list-item ${selected.id === item.id ? 'active' : ''}`} onClick={() => { setSelectedId(item.id); setScore(item.score); }}><span className="list-item-title"><span className="mono">{item.reference}</span><StatusChip status={item.status === 'pending' ? new Date(item.dueAt) < new Date() ? 'overdue' : 'under review' : item.status}/></span><span className="list-item-meta"><span>{item.title}</span></span><span className="list-item-meta"><span>{item.skill}</span><span>{item.score} / 100</span><span>{item.confidence} confidence</span></span><span className="list-item-meta"><Clock3 size={14}/><StatusChip status={isOverdue(item.dueAt) ? 'Overdue' : isDueSoon(item.dueAt) ? 'Due soon' : `Due ${formatDate(item.dueAt)}`}/></span></button>)}</div>
        <section className="split-detail" aria-labelledby="review-heading"><BackToQueue target="review-queue" label="Back to review queue"/><h2 id="review-heading" tabIndex={-1}>{selected.title}</h2><div className="mono">Submission {selected.reference}</div><div className="review-identity-note">Reviews are blind to the student's identity to reduce bias.</div>
          <div className="review-grid"><section className="review-pane"><h3>AI assessment</h3><div className="review-scoreline"><div className="proof-ring" role="img" aria-label={`${selected.skill}, AI score ${selected.score} of 100, ${selected.status === 'pending' ? 'under human review' : 'final decision recorded'}`}><svg viewBox="0 0 80 80" aria-hidden="true"><circle cx="40" cy="40" r="33" fill="none" stroke="var(--hairline)" strokeWidth="6"/><circle cx="40" cy="40" r="33" fill="none" stroke="var(--ember-500)" strokeWidth="6" strokeDasharray={`${selected.score * 2.07} 207`} strokeLinecap="round"/></svg><strong>{selected.score}</strong><small>AI score</small></div><div><div><StatusChip status={selected.status === 'pending' ? 'Under review' : selected.status}/></div><span className="small muted">{selected.confidence} confidence · {selected.skill}</span></div></div><p>{selected.summary}</p><div className="skill-row"><strong>{selected.skill}</strong><span>{selected.score} / 100</span><div className="skill-meter"><span style={{ width: `${selected.score}%` }}/></div></div><p className="muted small">{selected.rationale}</p>{selected.flags.map((flag) => <span className="status-chip pending" key={flag}><AlertTriangle size={14}/>{flag}</span>)}</section>
            <section className="review-pane"><h3>Evidence</h3><p><strong>{selected.title}</strong></p><p className="muted small">Submitted {formatDate(selected.submittedAt)} · Sample evidence excerpt</p><button className="button button-secondary button-small" onClick={() => setEvidenceOpen(true)}>Open evidence</button><pre className="evidence-block" style={{ marginTop: 12 }}>{selected.evidence}</pre><div className="notice">Student-provided links are shown only after a confirmation step.</div></section></div>
          {selected.status === 'pending' ? <div className="decision-bar"><div className="consequence">{verified ? `New score ${previewScore} → ${level} · Verified. It will become visible to organizations.` : `New score ${previewScore} → ${level} · Not verified. The result will be final after this decision.`}</div><div className="decision-actions"><button className="button button-secondary" onClick={() => { setScore(selected.score); setDialog('adjust'); }}>Adjust score…</button><button className="button button-primary" onClick={() => setDialog('confirm')}>Confirm score</button></div></div> : <div className="callout"><ShieldCheck size={18}/><span>Final human score: {selected.humanScore ?? selected.score} · {selected.status}. This review is read-only.</span></div>}
        </section></div>
      {dialog === 'confirm' ? <ConfirmForm title="Confirm this score?" consequence={`The score of ${selected.score} will be final. ${selected.score > passMark ? 'It will be visible to organizations.' : 'It will remain not verified.'}`} action="Confirm score" onCancel={() => setDialog(null)} onConfirm={() => { setDialog(null); stepUp.requireStepUp(() => mutation.mutate({ score: selected.score, adjusted: false })); }}/>: null}
      {dialog === 'adjust' ? <Modal title="Adjust score" onClose={() => setDialog(null)} footer={<><button className="button button-secondary" onClick={() => setDialog(null)}>Cancel</button><button className="button button-primary" disabled={reason.trim().length < 20 || !Number.isSafeInteger(score) || score < 0 || score > 100} onClick={() => { setDialog(null); stepUp.requireStepUp(() => mutation.mutate({ score, reason, adjusted: true })); }}>Save adjustment</button></>}><p className="muted">Adjust the score based on the work and evidence, not identity.</p><div className="field"><label htmlFor="adjust-score">New score</label><input id="adjust-score" className="input" type="number" min="0" max="100" value={score} onChange={(event) => setScore(Number(event.target.value))}/></div><div className="field"><label htmlFor="adjust-reason">Reason</label><textarea id="adjust-reason" className="textarea" value={reason} onChange={(event) => setReason(event.target.value)} maxLength={600}/><span className="field-hint">At least 20 characters. {reason.length}/600</span></div><div className="callout">New score {score} → {score > passMark ? 'Verified' : 'Not verified'}; this result will be final and will not be held again.</div></Modal> : null}
      {evidenceOpen ? <Modal title={`Evidence · ${selected.reference}`} onClose={() => setEvidenceOpen(false)} footer={<button className="button button-secondary" onClick={() => setEvidenceOpen(false)}>Close evidence</button>}><p className="review-identity-note">Blind evidence view · Sample excerpt. Student identity is not included.</p><pre className="evidence-block">{selected.evidence}</pre><p className="field-hint">Evidence content is rendered as plain text; external links and HTML are not opened here.</p></Modal> : null}
      {stepUp.modal}<ErrorText error={mutation.error}/>
    </>}
  </>;
}

export function TicketsPage() {
  const backend = useBackend(); const client = useQueryClient(); const toast = useToast(); const { user } = useAuth(); const stepUp = useStepUp();
  const query = useQuery({ queryKey: ['tickets'], queryFn: () => backend.tickets() }); const staff = useQuery({ queryKey: ['staff'], queryFn: () => backend.staff() }); const config = useQuery({ queryKey: ['config'], queryFn: () => backend.config() });
  const [selectedId, setSelectedId] = useState('tk-104'); const [dialog, setDialog] = useState<'assign' | 'decide' | null>(null); const [assignee, setAssignee] = useState('reviewer-2'); const [decision, setDecision] = useState<'upheld' | 'overturned' | 'adjusted'>('upheld'); const [reason, setReason] = useState(''); const [ticketScore, setTicketScore] = useState(52);
  const rows = query.data ?? []; const selected = rows.find((item) => item.id === selectedId) ?? rows[0];
  const mutation = useMutation({ mutationFn: (input: { action: 'ack' | 'assign' | 'decide'; assignee?: string; decision?: Ticket['decision']; reason?: string; adjustedScores?: Array<{ skillId: string; score: number }> }) => backend.updateTicket(selected.id, input.action, input.assignee, input.decision, input.reason, input.adjustedScores), onSuccess: async (_data, variables) => { toast(variables.action === 'ack' ? 'Ticket acknowledged.' : variables.action === 'assign' ? 'Reviewer assigned.' : 'Decision recorded.'); setDialog(null); setReason(''); await Promise.all([client.invalidateQueries({ queryKey: ['tickets'] }), client.invalidateQueries({ queryKey: ['counts'] }), client.invalidateQueries({ queryKey: ['audit-log'] })]); } });
  const reviewerOptions = (staff.data ?? []).filter((person) => person.role.toLowerCase() === 'admin' && person.id !== selected?.originalReviewerId);
  const originalReviewerIsCurrent = selected?.originalReviewerId === user?.id;
  const assignedReviewerIsCurrent = selected?.assigneeId === user?.id;
  const passMark = config.data?.PASS_MARK ?? 50;
  return <>
    <PageTitle title="Tickets" description="Appeals follow a separate, traceable review by a different reviewer." />
    <Stats items={[{ value: rows.filter((row) => row.status !== 'decided').length, label: 'Open appeals' }, { value: rows.filter((row) => row.status === 'open').length, label: 'Need acknowledgement' }, { value: rows.filter((row) => row.status === 'in_review').length, label: 'In review' }, { value: rows.filter((row) => row.status === 'decided').length, label: 'Decided' }]} />
    {query.isLoading ? <Loading text="Loading tickets"/> : query.isError ? <ErrorNotice retry={() => void query.refetch()}/> : !selected ? <div className="empty-state"><strong>No appeals waiting.</strong></div> : <div className="split-layout"><div id="ticket-queue" className="split-list" aria-label="Appeal tickets" tabIndex={-1}>{rows.map((item) => <button key={item.id} className={`list-item ${selected.id === item.id ? 'active' : ''}`} onClick={() => { setSelectedId(item.id); setTicketScore(item.score); }}><span className="list-item-title"><span className="mono">{item.reference}</span><StatusChip status={item.status === 'ack' ? 'Acknowledged' : item.status === 'in_review' ? 'In review' : item.status}/></span><span className="list-item-meta">{item.skill} · Original score {item.score}</span><span className="list-item-meta">{formatAge(item.createdAt)}{item.assignee ? ` · ${item.assignee}` : ''}</span></button>)}</div>
      <section className="split-detail"><BackToQueue target="ticket-queue" label="Back to tickets"/><span className="mono">{selected.reference}</span><div style={{ display: 'flex', justifyContent: 'space-between', gap: 10, alignItems: 'center' }}><h2>Appeal · {selected.skill}</h2><StatusChip status={selected.status}/></div><div className="detail-section"><h3>Reason from the student</h3><p>{selected.reason}</p></div><div className="detail-section"><h3>Original review</h3><p className="review-identity-note">This view is blind to the student's identity.</p><div className="review-scoreline"><div className="proof-ring" role="img" aria-label={`${selected.skill}, score ${selected.score} of 100, under review`}><svg viewBox="0 0 80 80"><circle cx="40" cy="40" r="33" fill="none" stroke="var(--hairline)" strokeWidth="6"/><circle cx="40" cy="40" r="33" fill="none" stroke="var(--verdant-600)" strokeWidth="6" strokeDasharray={`${selected.score * 2.07} 207`}/></svg><strong>{selected.score}</strong></div><span>{selected.skill} · Original score</span></div><div className="notice">Original review: confirmed by {originalReviewerIsCurrent ? 'you' : selected.originalReviewer}.</div><pre className="evidence-block">Evidence excerpt · Sample

The original assessment and evidence are shown without student identity.</pre></div>
        <div className="detail-section"><h3>Decision timeline</h3><div className="check-row"><Check size={18} className="check-icon"/><span>Ticket received · {formatDate(selected.createdAt)}</span></div><div className="check-row"><Clock3 size={18} className="check-icon"/><span>{selected.status === 'open' ? 'Awaiting acknowledgement' : selected.status === 'decided' ? `Decision recorded: ${selected.decision}` : 'Acknowledged and assigned for review'}</span></div></div>
        {selected.status === 'open' ? <button className="button button-primary" onClick={() => mutation.mutate({ action: 'ack' })}>Acknowledge ticket</button> : null}
        {selected.status === 'ack' ? <button className="button button-primary" onClick={() => { setAssignee(reviewerOptions[0]?.id ?? ''); setDialog('assign'); }}>Assign reviewer</button> : null}
        {selected.status === 'in_review' ? <><div className="notice">{originalReviewerIsCurrent ? 'You confirmed the original review, so a different reviewer must decide this appeal.' : assignedReviewerIsCurrent ? `Assigned to you (${selected.assignee ?? 'reviewer'}). You may decide this appeal.` : `Assigned to ${selected.assignee ?? 'another reviewer'}. Only that reviewer may decide this appeal.`}</div><button className="button button-primary" disabled={originalReviewerIsCurrent || !assignedReviewerIsCurrent} onClick={() => setDialog('decide')}>Decide appeal</button></> : null}
        {selected.status === 'decided' ? <div className="callout"><Check size={18}/><span>Decision: {selected.decision}. This ticket is read-only.</span></div> : null}
      </section></div>}
    {dialog === 'assign' ? <Modal title="Assign a different reviewer" onClose={() => setDialog(null)} footer={<><button className="button button-secondary" onClick={() => setDialog(null)}>Cancel</button><button className="button button-primary" disabled={!assignee || assignee === selected?.originalReviewerId} onClick={() => { const reviewerId = assignee; setDialog(null); stepUp.requireStepUp(() => mutation.mutate({ action: 'assign', assignee: reviewerId })); }}>Assign reviewer</button></>}><p>Choose someone other than the reviewer who confirmed the original result.</p>{reviewerOptions.length ? <div className="field"><label htmlFor="reviewer-select">Reviewer</label><select className="select" id="reviewer-select" value={assignee} onChange={(event) => setAssignee(event.target.value)}>{reviewerOptions.map((person) => <option key={person.id} value={person.id}>{person.name}</option>)}</select></div> : <div className="notice">No other reviewer is available. Add another admin first.</div>}</Modal> : null}
    {dialog === 'decide' ? <Modal title="Decide appeal" onClose={() => setDialog(null)} footer={<><button className="button button-secondary" onClick={() => setDialog(null)}>Cancel</button><button className="button button-primary" disabled={reason.trim().length < 20 || (decision === 'adjusted' && (!selected?.skillId || !Number.isSafeInteger(ticketScore) || ticketScore < 0 || ticketScore > 100))} onClick={() => { const input = { action: 'decide' as const, decision, reason, adjustedScores: decision === 'adjusted' && selected?.skillId ? [{ skillId: selected.skillId, score: ticketScore }] : undefined }; setDialog(null); stepUp.requireStepUp(() => mutation.mutate(input)); }}>Record decision</button></>}><p>This is recorded in the rubric improvement log and the student is notified.</p><div className="field"><label htmlFor="ticket-decision">Decision</label><select className="select" id="ticket-decision" value={decision} onChange={(event) => setDecision(event.target.value as typeof decision)}><option value="upheld">Upheld · Original score stands</option><option value="overturned">Overturned</option><option value="adjusted" disabled={!selected?.skillId}>Adjusted</option></select></div>{decision === 'adjusted' ? <><div className="field"><label htmlFor="ticket-new-score">Adjusted score</label><input className="input" id="ticket-new-score" type="number" min="0" max="100" value={ticketScore} onChange={(event) => setTicketScore(Number(event.target.value))}/></div><div className="notice">New score {ticketScore} → {levelFor(ticketScore)} · {isVerified(ticketScore, passMark) ? 'Verified' : 'Not verified'}. The decision will be final.</div></> : null}<div className="field"><label htmlFor="ticket-reason">Reason</label><textarea className="textarea" id="ticket-reason" value={reason} onChange={(event) => setReason(event.target.value)} maxLength={600}/><span className="field-hint">At least 20 characters. {reason.length}/600</span></div></Modal> : null}
    {stepUp.modal}<ErrorText error={mutation.error}/>
  </>;
}

export function RunsPage() {
  const backend = useBackend(); const client = useQueryClient(); const toast = useToast(); const stepUp = useStepUp();
  const [filter, setFilter] = useState('all'); const [autoRefresh, setAutoRefresh] = useState(false); const [selected, setSelected] = useState<AgentRun | null>(null); const [confirm, setConfirm] = useState<AgentRun | null>(null);
  const query = useQuery({ queryKey: ['runs'], queryFn: () => backend.runs(), refetchInterval: autoRefresh ? 10_000 : false }); const config = useQuery({ queryKey: ['config'], queryFn: () => backend.config() });
  const failed = (query.data ?? []).filter((run) => run.status === 'failed' || run.status === 'timeout'); const visible = (query.data ?? []).filter((run) => filter === 'all' || run.status === filter);
  const mutation = useMutation({ mutationFn: (run: AgentRun) => backend.retryRun(run.id), onSuccess: async () => { toast('Run queued.'); setConfirm(null); await Promise.all([client.invalidateQueries({ queryKey: ['runs'] }), client.invalidateQueries({ queryKey: ['counts'] }), client.invalidateQueries({ queryKey: ['audit-log'] })]); } });
  const median = useMemo(() => { const sorted = [...(query.data ?? [])].map((run) => run.latency).sort((a, b) => a - b); if (!sorted.length) return '—'; const middle = Math.floor(sorted.length / 2); const value = sorted.length % 2 ? sorted[middle] ?? 0 : ((sorted[middle - 1] ?? 0) + (sorted[middle] ?? 0)) / 2; return `${Math.round(value)} ms`; }, [query.data]);
  return <><PageTitle title="Agent runs" description="Monitor agent activity, failures, latency and retry history." action={<label className="checkbox-line"><input type="checkbox" checked={autoRefresh} onChange={(event) => setAutoRefresh(event.target.checked)}/>Auto-refresh every 10 sec</label>}/>
    <div className="callout"><Activity size={19}/><span>Mode: <StatusChip status={config.data?.AGENT_MODE ?? 'mock'}/> &nbsp;·&nbsp; AI kill switch: <StatusChip status={config.data?.AI_KILL_SWITCH ? 'Paused' : 'Off'}/> &nbsp;<a href="/settings">Settings</a></span></div>
    <Stats items={[{ value: query.data?.length ?? '—', label: 'Runs in this sample window' }, { value: query.data?.length ? `${Math.round((failed.length / query.data.length) * 100)}%` : '—', label: 'Failure rate' }, { value: median, label: 'Median latency' }, { value: 'Sample', label: 'Estimated tokens today' }]}/>
    <div className="toolbar"><select className="pill-filter" value={filter} onChange={(event) => setFilter(event.target.value)} aria-label="Filter runs"><option value="all">All statuses</option><option value="failed">Failed</option><option value="timeout">Timeout</option><option value="running">Running</option><option value="succeeded">Succeeded</option></select><span className="field-hint">Based on a local sample window.</span></div>
    {query.isLoading ? <Loading text="Loading agent runs"/> : query.isError ? <ErrorNotice retry={() => void query.refetch()}/> : <Table label="Agent runs" headers={['Run', 'Kind', 'Mode', 'Status', 'Stage', 'Latency', 'Tokens in / out', 'Submission', 'Started', 'Action']}>{visible.map((run) => <tr key={run.id} onClick={() => setSelected(run)}>{cell('Run', <span className="mono">{run.id}</span>)}{cell('Kind', run.kind)}{cell('Mode', <span className="mono">{run.mode}</span>)}{cell('Status', <StatusChip status={run.status}/>)}{cell('Stage', run.stage)}{cell('Latency', `${run.latency} ms`)}{cell('Tokens in / out', `${run.tokensIn} / ${run.tokensOut}`)}{cell('Submission', <span className="mono">{run.reference}</span>)}{cell('Started', formatAge(run.createdAt))}{cell('Action', ['failed', 'timeout'].includes(run.status) ? <button className="row-action" disabled={config.data?.AI_KILL_SWITCH} onClick={(event) => { event.stopPropagation(); setConfirm(run); }}>Retry</button> : '—')}</tr>)}</Table>}
    {selected ? <Modal title={`Run ${selected.id}`} onClose={() => setSelected(null)} footer={<button className="button button-secondary back-button" onClick={() => setSelected(null)}><ArrowLeft size={16} aria-hidden="true"/>Back to runs</button>}><dl className="detail-grid"><div className="detail-cell"><dt>Status</dt><dd><StatusChip status={selected.status}/></dd></div><div className="detail-cell"><dt>Stage</dt><dd>{selected.stage}</dd></div><div className="detail-cell"><dt>Mode</dt><dd>{selected.mode}</dd></div><div className="detail-cell"><dt>Attempt</dt><dd>{selected.attempt}</dd></div><div className="detail-cell"><dt>Input / output tokens</dt><dd>{selected.tokensIn} / {selected.tokensOut}</dd></div></dl>{selected.error ? <pre className="evidence-block">{selected.error}</pre> : <p className="muted">No error reported for this run.</p>}</Modal> : null}
    {confirm ? <ConfirmForm title="Retry this run?" consequence="Retry uses the current mode, AI limits and kill switch." action="Retry run" onCancel={() => setConfirm(null)} onConfirm={() => { const run = confirm; setConfirm(null); stepUp.requireStepUp(() => mutation.mutate(run)); }}/>: null}{stepUp.modal}<ErrorText error={mutation.error}/>
    <div aria-live="polite" className="field-hint" style={{ marginTop: 8 }}>{autoRefresh ? `Auto-refresh is on. Updated ${query.dataUpdatedAt ? new Date(query.dataUpdatedAt).toLocaleTimeString() : 'just now'}.` : ''}</div>
  </>;
}

export function SettingsPage() {
  const backend = useBackend(); const client = useQueryClient(); const toast = useToast(); const config = useQuery({ queryKey: ['config'], queryFn: () => backend.config() });
  const [values, setValues] = useState<Partial<AppConfig>>({}); const [confirm, setConfirm] = useState<{ key: keyof AppConfig; value: unknown } | null>(null); const [stepUp, setStepUp] = useState<{ key: keyof AppConfig; value: unknown; reason?: string } | null>(null); const [code, setCode] = useState(''); const [stepError, setStepError] = useState(''); const [verifying, setVerifying] = useState(false); const [resetDialog, setResetDialog] = useState(false);
  const mutation = useMutation({ mutationFn: (input: { key: keyof AppConfig; value: unknown; reason?: string }) => backend.updateConfig({ key: input.key, value: input.value, reason: input.reason }), onSuccess: async () => { toast('Setting saved.'); setStepUp(null); setConfirm(null); setCode(''); setValues({}); await Promise.all([client.invalidateQueries({ queryKey: ['config'] }), client.invalidateQueries({ queryKey: ['audit-log'] })]); } });
  const current = config.data; const value = <K extends keyof AppConfig>(key: K): AppConfig[K] => values[key] as AppConfig[K] ?? current?.[key] as AppConfig[K];
  const save = (key: keyof AppConfig): void => {
    const changed = values[key] ?? current?.[key];
    if (changed === undefined) return;
    const invalid = key === 'PASS_MARK' ? !passMarkSchema.safeParse(changed).success
      : key === 'BORDERLINE' ? !borderlineSchema.safeParse(changed).success
      : key === 'VIDEO_MAX_MB' ? !videoLimitSchema.safeParse(changed).success
      : key === 'VIDEO_MAX_SECONDS' ? !durationSchema.safeParse(changed).success
      : key === 'AI_DAILY_CAP_PER_USER' ? !dailyCapSchema.safeParse(changed).success : false;
    if (invalid) { toast(key === 'BORDERLINE' ? 'Enter a range from 0 to 100 with the lower score below the upper score.' : 'Enter a value within the allowed range.'); return; }
    if (['AI_KILL_SWITCH', 'AGENT_MODE', 'PASS_MARK', 'BORDERLINE'].includes(key)) setConfirm({ key, value: changed });
    else setStepUp({ key, value: changed });
  };
  const destructive = confirm?.key === 'AI_KILL_SWITCH';
  const dangerous = confirm && ['AI_KILL_SWITCH', 'AGENT_MODE', 'PASS_MARK', 'BORDERLINE'].includes(confirm.key);
  const reasonNeeded = confirm && ['AGENT_MODE', 'PASS_MARK', 'BORDERLINE'].includes(confirm.key);
  const titleFor = (key: keyof AppConfig): string => key === 'AI_KILL_SWITCH' ? Boolean(confirm?.value) ? 'Pause AI?' : 'Resume AI?' : `Save ${key.replaceAll('_', ' ').toLowerCase()}?`;
  const consequenceFor = (key: keyof AppConfig, next: unknown): string => key === 'AI_KILL_SWITCH' ? Boolean(next) ? 'Pause all AI reviews and project assignments. Students keep their drafts.' : 'Resume AI reviews and project assignments.' : `This changes ${key.replaceAll('_', ' ').toLowerCase()} from ${String(current?.[key] ?? '—')} to ${String(next)}. This affects future work.`;
  const commitDanger = (reason?: string): void => { if (!confirm) return; if (destructive) { setStepUp({ ...confirm, reason }); setConfirm(null); } else { setStepUp({ ...confirm, reason }); setConfirm(null); } };
  const stepVerify = async (): Promise<void> => {
    if (code.length !== 6 || verifying) return;
    setVerifying(true); setStepError('');
    try {
      await backend.auth.verifyMfa(code);
      if (stepUp?.value === 'RESET') { await backend.resetDemo(); toast('Demo data reset.'); setStepUp(null); setCode(''); await client.invalidateQueries(); }
      else if (stepUp) { mutation.mutate({ ...stepUp, reason: stepUp.reason }); }
    } catch { setCode(''); setStepError('The code could not be verified or the action failed. Check your authenticator and try again.'); }
    finally { setVerifying(false); }
  };
  if (config.isLoading) return <><PageTitle title="Settings" description="Manage the controls that shape AI work and student submissions."/><Loading text="Loading settings"/></>;
  if (config.isError || !current) return <><PageTitle title="Settings" description="Manage the controls that shape AI work and student submissions."/><ErrorNotice retry={() => void config.refetch()}/></>;
  const row = (key: keyof AppConfig, label: string, description: string, control: ReactNode) => <div className="setting-row" key={key}><div><div className="setting-title">{label}</div><div className="setting-description">{description}</div><div className="setting-meta">Current: {String(current[key])}</div></div><div className="setting-value">{control}</div><button className="button button-secondary button-small" onClick={() => save(key)}>Save</button></div>;
  return <><PageTitle title="Settings" description="Manage the controls that shape AI work and student submissions."/><div className="tabs" role="tablist" aria-label="Settings sections"><button className="tab-button" role="tab" aria-selected="true">Configuration</button>{!isProductionBuild ? <button className="tab-button" role="tab" aria-selected="false" onClick={() => setResetDialog(true)}>Demo data</button> : null}</div>
    <div className="callout danger"><LockKeyhole size={20}/><span><strong>AI kill switch</strong><br/>{current.AI_KILL_SWITCH ? 'AI is paused.' : 'AI is currently available.'} Changes require two-step verification.</span></div>
    <div className="settings-list">
      {row('AI_KILL_SWITCH', 'AI kill switch', 'Pause all AI reviews and project assignments.', <div className="segmented" role="group" aria-label="AI kill switch"><button aria-pressed={!value('AI_KILL_SWITCH')} onClick={() => setValues({ ...values, AI_KILL_SWITCH: false })}>Off</button><button aria-pressed={value('AI_KILL_SWITCH')} onClick={() => setValues({ ...values, AI_KILL_SWITCH: true })}>On</button></div>)}
      {row('AGENT_MODE', 'Agent mode', 'Real student reviews never fall back to mock silently.', <select className="select" aria-label="Agent mode" value={value('AGENT_MODE')} onChange={(event) => setValues({ ...values, AGENT_MODE: event.target.value as AppConfig['AGENT_MODE'] })}><option value="mock">mock</option><option value="direct">direct</option><option value="n8n">n8n</option></select>)}
      {row('PASS_MARK', 'Pass mark', 'Verified means a score is above the pass mark.', <input className="input" aria-label="Pass mark" type="number" min="1" max="99" value={value('PASS_MARK')} onChange={(event) => setValues({ ...values, PASS_MARK: Number(event.target.value) })}/>)}
      {row('BORDERLINE', 'Borderline range', 'Scores in this range are held for human review.', <div className="config-input"><input aria-label="Borderline low" className="input" type="number" value={value('BORDERLINE')[0]} onChange={(event) => setValues({ ...values, BORDERLINE: [Number(event.target.value), value('BORDERLINE')[1]] })}/><span>to</span><input aria-label="Borderline high" className="input" type="number" value={value('BORDERLINE')[1]} onChange={(event) => setValues({ ...values, BORDERLINE: [value('BORDERLINE')[0], Number(event.target.value)] })}/></div>)}
      {row('REQUIRE_VIDEO', 'Require video', 'Students must add a demo video or video link before submitting.', <div className="segmented" role="group" aria-label="Require video setting"><button aria-pressed={value('REQUIRE_VIDEO')} onClick={() => setValues({ ...values, REQUIRE_VIDEO: true })}>Required</button><button aria-pressed={!value('REQUIRE_VIDEO')} onClick={() => setValues({ ...values, REQUIRE_VIDEO: false })}>Optional</button></div>)}
      {row('VIDEO_MAX_MB', 'Video size limit', 'Check your storage plan’s per-file limit before raising this.', <input className="input" aria-label="Video size limit in megabytes" type="number" min="1" max="500" value={value('VIDEO_MAX_MB')} onChange={(event) => setValues({ ...values, VIDEO_MAX_MB: Number(event.target.value) })}/>)}
      {row('VIDEO_MAX_SECONDS', 'Video duration limit', 'Current duration limit in seconds.', <input className="input" aria-label="Video duration limit in seconds" type="number" min="30" max="600" value={value('VIDEO_MAX_SECONDS')} onChange={(event) => setValues({ ...values, VIDEO_MAX_SECONDS: Number(event.target.value) })}/>)}
      {row('AI_DAILY_CAP_PER_USER', 'Daily AI cap per user', 'Reviews and project assignments per student per day. Zero means none allowed.', <input className="input" aria-label="Daily AI cap per user" type="number" min="0" max="50" value={value('AI_DAILY_CAP_PER_USER')} onChange={(event) => setValues({ ...values, AI_DAILY_CAP_PER_USER: Number(event.target.value) })}/>)}
    </div>
    {confirm && dangerous ? <ConfirmForm title={titleFor(confirm.key)} consequence={consequenceFor(confirm.key, confirm.value)} action={destructive ? Boolean(confirm.value) ? 'Pause AI' : 'Resume AI' : 'Continue'} requiredWord={destructive ? Boolean(confirm.value) ? 'PAUSE' : 'RESUME' : undefined} needsReason={Boolean(reasonNeeded)} reasonMin={20} onCancel={() => setConfirm(null)} onConfirm={commitDanger}/> : null}
    {stepUp ? <Modal title="Confirm with your authenticator" onClose={() => { if (!verifying) { setStepUp(null); setCode(''); setStepError(''); } }} footer={<><button className="button button-secondary" disabled={verifying} onClick={() => { setStepUp(null); setCode(''); setStepError(''); }}>Cancel</button><button className="button button-primary" disabled={code.length !== 6 || verifying} onClick={() => void stepVerify()}>{verifying ? 'Verifying…' : 'Verify and save'}</button></>}><p>{demoFeaturesEnabled ? 'Enter the six-digit code from your authenticator app. In mock mode only, use the demo code shown in the project guide.' : 'Enter the six-digit code from your authenticator app to confirm this sensitive change.'}</p><div className="field"><label htmlFor="step-code">Authenticator code</label><input id="step-code" className="input" inputMode="numeric" autoComplete="one-time-code" maxLength={6} value={code} onChange={(event) => setCode(event.target.value.replace(/\D/g, '').slice(0, 6))}/>{stepError ? <span className="field-hint" role="alert">{stepError}</span> : null}</div></Modal> : null}
    {resetDialog ? <ConfirmForm title="Reset demo data?" consequence="This replaces all demo data with the original fictional data. Real data is never touched." action="Reset" requiredWord="RESET" onCancel={() => setResetDialog(false)} onConfirm={() => { setResetDialog(false); setStepUp({ key: 'PASS_MARK', value: 'RESET' }); }}/> : null}
    <ErrorText error={mutation.error}/>
  </>;
}

export function LibraryPage() {
  const [tab, setTab] = useState<'skills' | 'templates'>('skills');
  return <><PageTitle title="Library" description="Starter skill taxonomy and project templates. Changes affect new projects and reviews only."/><div className="tabs" role="tablist" aria-label="Library sections"><button className="tab-button" role="tab" aria-selected={tab === 'skills'} onClick={() => setTab('skills')}>Skills</button><button className="tab-button" role="tab" aria-selected={tab === 'templates'} onClick={() => setTab('templates')}>Project templates</button></div>{tab === 'skills' ? <Table label="Skill taxonomy" headers={['Name', 'Slug', 'Family', 'Related skills', 'Active']}><tr>{cell('Name', 'Frontend development')}{cell('Slug', <span className="mono">frontend</span>)}{cell('Family', 'Web')}{cell('Related skills', 'React · Accessibility')}{cell('Active', <StatusChip status="active"/>)}</tr><tr>{cell('Name', 'Backend development')}{cell('Slug', <span className="mono">backend</span>)}{cell('Family', 'Engineering')}{cell('Related skills', 'Data · APIs')}{cell('Active', <StatusChip status="active"/>)}</tr><tr>{cell('Name', 'Data analysis')}{cell('Slug', <span className="mono">data-analysis</span>)}{cell('Family', 'Data')}{cell('Related skills', 'Backend')}{cell('Active', <StatusChip status="active"/>)}</tr></Table> : <Table label="Project templates" headers={['Title', 'Skill', 'Level', 'Estimated hours', 'Active']}><tr>{cell('Title', 'Build a product catalogue')}{cell('Skill', 'Frontend development')}{cell('Level', 'Competent')}{cell('Estimated hours', '8')}{cell('Active', <StatusChip status="active"/>)}</tr><tr>{cell('Title', 'Design an accessible booking flow')}{cell('Skill', 'Frontend development')}{cell('Level', 'Proficient')}{cell('Estimated hours', '12')}{cell('Active', <StatusChip status="active"/>)}</tr></Table>}<div className="notice">Editing is not enabled until the shared backend contract confirms writable library fields. Rubrics are read-only.</div></>;
}

export function AuditLogPage() {
  const backend = useBackend(); const stepUp = useStepUp();
  const query = useQuery({ queryKey: ['audit-log'], queryFn: () => backend.auditLog() });
  const [search, setSearch] = useState(''); const [action, setAction] = useState('all'); const [from, setFrom] = useState(''); const [to, setTo] = useState(''); const [exportOpen, setExportOpen] = useState(false);
  const actions = [...new Set((query.data ?? []).map((row) => row.action))].sort();
  const logs = (query.data ?? []).filter((row) => {
    const matchesSearch = `${row.actor} ${row.role} ${row.action} ${row.target} ${row.detail}`.toLowerCase().includes(search.toLowerCase());
    const date = row.at.slice(0, 10);
    return matchesSearch && (action === 'all' || row.action === action) && (!from || date >= from) && (!to || date <= to);
  });
  const makeCsv = (): string => toCsv([['Time','Actor','Role','Action','Target','Details','Sensitive'], ...logs.map((row) => [row.at,row.actor,row.role,row.action,row.target,row.detail,row.sensitive ? 'Yes' : 'No'])]);
  const download = (): void => {
    const csv = makeCsv(); const url = URL.createObjectURL(new Blob([csv], { type: 'text/csv;charset=utf-8' })); const link = document.createElement('a');
    link.href = url; link.download = env.VITE_USE_MOCKS ? 'aptohire-audit-log-sample.csv' : 'aptohire-audit-log.csv'; document.body.appendChild(link); link.click(); link.remove(); window.setTimeout(() => URL.revokeObjectURL(url), 1000); setExportOpen(false);
  };
  return <><PageTitle title="Audit log" description="Append-only record of consequential actions and sensitive reads." action={<button className="button button-secondary" disabled={!logs.length} onClick={() => setExportOpen(true)}><FileText size={16}/>Export CSV</button>}/>
    <div className="callout"><ShieldCheck size={20}/><span>This log is read-only. {env.VITE_USE_MOCKS ? 'Sample entries are fictional.' : 'Only sanitized event summaries are displayed.'}</span></div>
    <div className="toolbar"><label className="searchbox"><Search size={17}/><input className="input" value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Search action, actor or target" aria-label="Search audit log"/></label><select className="pill-filter" aria-label="Filter audit actions" value={action} onChange={(event) => setAction(event.target.value)}><option value="all">All actions</option>{actions.map((item) => <option key={item} value={item}>{item}</option>)}</select><label className="field-hint">From <input aria-label="Audit start date" type="date" value={from} onChange={(event) => setFrom(event.target.value)}/></label><label className="field-hint">To <input aria-label="Audit end date" type="date" value={to} onChange={(event) => setTo(event.target.value)}/></label></div>
    {query.isLoading ? <Loading text="Loading audit activity"/> : query.isError ? <ErrorNotice retry={() => void query.refetch()}/> : logs.length ? <><Table label="Audit log" headers={['Time', 'Actor', 'Action', 'Target', 'Details']}>{logs.map((row) => <tr key={row.id}>{cell('Time', new Intl.DateTimeFormat('en-IN', { dateStyle: 'medium', timeStyle: 'short' }).format(new Date(row.at)))}{cell('Actor', <>{row.actor}<span className="small muted" style={{ display: 'block' }}>{row.role}</span></>)}{cell('Action', row.action)}{cell('Target', <span className="mono">{row.target}</span>)}{cell('Details', <>{row.detail}{row.sensitive ? <span className="status-chip pending" style={{ display: 'block', marginTop: 5 }}>Sensitive read</span> : null}</>)}</tr>)}</Table><p className="field-hint" style={{ marginTop: 12 }}>Showing {logs.length} filtered event{logs.length === 1 ? '' : 's'} · newest first.</p></> : <div className="empty-state"><strong>No audit events match.</strong><span>Try changing the search or filters.</span></div>}
    {exportOpen ? <ConfirmForm title="Export audit activity?" consequence="This file contains administrative activity. Store it securely." action="Export CSV" onCancel={() => setExportOpen(false)} onConfirm={() => { setExportOpen(false); stepUp.requireStepUp(download); }}/>: null}
    {stepUp.modal}
  </>;
}

export function UsersPage() {
  const backend = useBackend(); const query = useQuery({ queryKey: ['staff'], queryFn: () => backend.staff() });
  return <><PageTitle title="Users" description="Read-only view of staff roles and operational access."/><div className="callout"><LockKeyhole size={20}/><span>AptoHire doesn't allow impersonation.</span></div><p className="muted">Role changes, invitations and account controls are intentionally not available here.</p>{query.isLoading ? <Loading text="Loading staff"/> : query.isError ? <ErrorNotice retry={() => void query.refetch()}/> : <Table label="Staff list" headers={['Name or label', 'Role', 'Organization', 'Created', 'Last sign-in']}>{(query.data ?? []).map((person) => <tr key={person.id}>{cell('Name or label', person.name)}{cell('Role', person.role)}{cell('Organization', '—')}{cell('Created', 'Sample')}{cell('Last sign-in', 'Sample')}</tr>)}</Table>}</>;
}

export function ReportsPage() {
  const backend = useBackend(); const stepUp = useStepUp(); const query = useQuery({ queryKey: ['reviews'], queryFn: () => backend.reviews() }); const config = useQuery({ queryKey: ['config'], queryFn: () => backend.config() }); const [exportOpen, setExportOpen] = useState(false);
  const passMark = config.data?.PASS_MARK ?? 50;
  const decisions = (query.data ?? []).filter((item) => item.status !== 'pending' && item.humanScore !== undefined);
  const comparable = decisions.map((item) => ({ aiScore: item.score, humanScore: item.humanScore ?? item.score, outcome: item.status as 'confirmed' | 'adjusted' }));
  const agreementPercent = comparable.length ? Math.round((comparable.filter(agrees).length / comparable.length) * 100) : null;
  const falsePassPercent = comparable.length ? Math.round((comparable.filter((item) => isFalsePass(item, passMark)).length / comparable.length) * 100) : null;
  const adjusted = comparable.filter((item) => item.outcome === 'adjusted');
  const averageAdjustment = adjusted.length ? (adjusted.reduce((sum, item) => sum + Math.abs(item.aiScore - item.humanScore), 0) / adjusted.length).toFixed(1) : null;
  const recent = [...decisions].sort((a, b) => b.submittedAt.localeCompare(a.submittedAt)).slice(0, 25);
  const sampleLabel = env.VITE_USE_MOCKS ? ' · Sample' : '';
  const exportRows = (): void => {
    const csv = toCsv([['Submission reference','Skill','AI score','Human score','Outcome'], ...recent.map((item) => [item.reference,item.skill,item.score,item.humanScore ?? '',item.status])]);
    const url = URL.createObjectURL(new Blob([csv], { type: 'text/csv;charset=utf-8' })); const link = document.createElement('a');
    link.href = url; link.download = env.VITE_USE_MOCKS ? 'aptohire-agreement-sample.csv' : 'aptohire-agreement.csv'; document.body.appendChild(link); link.click(); link.remove(); window.setTimeout(() => URL.revokeObjectURL(url), 1000); setExportOpen(false);
  };
  return <><PageTitle title="Reports" description="AI and human review agreement, calculated from completed blind-review decisions." action={<button className="button button-secondary" disabled={!recent.length} onClick={() => setExportOpen(true)}>Export CSV</button>}/>
    {query.isLoading ? <Loading text="Loading review decisions"/> : query.isError ? <ErrorNotice retry={() => void query.refetch()}/> : <>
      <Stats items={[{ value: agreementPercent === null ? '—' : `${agreementPercent}%`, label: `Agreement rate${sampleLabel}` }, { value: decisions.length, label: `Completed reviews${sampleLabel}` }, { value: falsePassPercent === null ? '—' : `${falsePassPercent}%`, label: `False-pass rate${sampleLabel}` }, { value: averageAdjustment ?? '—', label: `Average adjustment · points${sampleLabel}` }]}/>
      <h2>Agreement toward the 80% target</h2><p className="muted">Agreement treats confirmed reviews as a match and adjusted reviews within {AGREEMENT_TOLERANCE} points as a match. Small samples are descriptive only.</p>
      <div className="report-progress" role="meter" aria-label="Review agreement rate" aria-valuemin={0} aria-valuemax={100} aria-valuenow={agreementPercent ?? 0}><span style={{ width: `${agreementPercent ?? 0}%` }}/></div>
      {agreementPercent === null ? <div className="field-hint">No completed decisions are available yet.</div> : <div className="field-hint">{agreementPercent}% agreement · {decisions.length} decision{decisions.length === 1 ? '' : 's'} · {isSmallSample(decisions.length) ? 'Sample is too small for a stable rate.' : 'Interpret with the current review sample.'}{sampleLabel}</div>}
      <div style={{ marginTop: 24 }}><h2>Recent blind review decisions</h2>{recent.length ? <Table label="Recent review decisions" headers={['Submission reference', 'Skill', 'AI score', 'Human score', 'Outcome']}>{recent.map((item) => <tr key={item.id}>{cell('Submission reference', <span className="mono">{item.reference}</span>)}{cell('Skill', item.skill)}{cell('AI score', item.score)}{cell('Human score', item.humanScore ?? '—')}{cell('Outcome', <StatusChip status={item.status}/>)}</tr>)}</Table> : <div className="empty-state"><strong>No completed reviews yet.</strong><span>Review agreement will appear after human decisions are recorded.</span></div>}</div>
    </>}
    {exportOpen ? <ConfirmForm title="Export agreement report?" consequence="This export contains score decisions. Store it securely." action="Export CSV" onCancel={() => setExportOpen(false)} onConfirm={() => { setExportOpen(false); stepUp.requireStepUp(exportRows); }}/>: null}
    {stepUp.modal}
  </>;
}

export function NotificationsPage() {
  const backend = useBackend(); const client = useQueryClient(); const navigate = useNavigate(); const toast = useToast();
  const query = useQuery({ queryKey: ['notifications'], queryFn: () => backend.notifications(), refetchInterval: 60_000 });
  const mutation = useMutation({ mutationFn: () => backend.markNotificationsRead(), onSuccess: async () => { toast('Notifications marked as read.'); await client.invalidateQueries({ queryKey: ['notifications'] }); } });
  const items = query.data ?? []; const unread = items.filter((item) => !item.readAt).length;
  const openItem = (item: NotificationItem): void => { if (item.href?.startsWith('/') && !item.href.startsWith('//')) navigate(item.href); };
  return <><PageTitle title="Notifications" description="Updates about approvals, reviews, tickets and agent runs." action={<button className="button button-secondary" disabled={!unread || mutation.isPending} onClick={() => mutation.mutate()}>Mark all read</button>}/>
    {unread ? <div className="notice" role="status">{unread} unread update{unread === 1 ? '' : 's'}.</div> : null}
    {query.isLoading ? <Loading text="Loading notifications"/> : query.isError ? <ErrorNotice retry={() => void query.refetch()}/> : items.length ? <div className="notification-list">{items.map((item) => <article className={`notification-item ${item.readAt ? 'read' : 'unread'}`} key={item.id}><div className="notification-content"><div className="notification-heading"><h2>{item.title}</h2><StatusChip status={item.readAt ? 'Read' : 'Unread'}/></div><p>{item.body}</p><span className="field-hint">{formatDate(item.at)} · {formatAge(item.at)}</span></div>{item.href?.startsWith('/') && !item.href.startsWith('//') ? <button className="button button-secondary button-small" onClick={() => openItem(item)}>Open</button> : null}</article>)}</div> : <div className="empty-state"><div className="empty-orbit"/><strong>You're all caught up.</strong><span>New updates will appear here.</span></div>}
    <ErrorText error={mutation.error}/>
  </>;
}
export function AccountPage() { const { user, signOut } = useAuth(); return <><PageTitle title="Account & security" description="Your admin session and authentication status."/><div className="detail-section"><dl className="detail-grid"><div className="detail-cell"><dt>Email</dt><dd>{user?.email}</dd></div><div className="detail-cell"><dt>Role</dt><dd>Admin</dd></div><div className="detail-cell"><dt>Two-step verification</dt><dd><StatusChip status="Enrolled"/></dd></div><div className="detail-cell"><dt>Assurance</dt><dd>Verified for this session</dd></div></dl></div><p className="muted">To reset your authenticator, ask another admin.</p><button className="button button-secondary" onClick={() => void signOut()}>Sign out of all devices</button></>; }
export function HelpPage() { return <><PageTitle title="Help" description="Operational guidance for fair and secure admin work."/><div className="detail-section"><h2>Review and appeal</h2><p>Borderline results stay private until a human confirms or adjusts the score. Appeals are assigned to a reviewer who did not confirm the original result.</p><h2>The AI kill switch</h2><p>Pausing AI blocks new reviews and project assignments. Students keep their drafts. Turn the switch off only after the issue is understood.</p><h2>Security reminders</h2><p>Never share your authenticator code. Lock your screen when you step away. Consequential actions are recorded in the audit log.</p><p>For support, contact <a href={`mailto:${env.VITE_SUPPORT_EMAIL}`}>{env.VITE_SUPPORT_EMAIL}</a>.</p></div></>; }

export function NotFoundPage() { const navigate = useNavigate(); return <div className="wrong-role"><div className="wrong-role-box"><h1>That page doesn't exist.</h1><p className="muted">Check the address or return to Approvals.</p><button className="button button-primary" onClick={() => navigate('/approvals')}>Go home</button></div></div>; }
